# Particles in Python: 100k particles, the hot loop touches 2 of 5 fields.
from array import array as _vsc_array
# Generated by Viscosity: bounds check matching list's IndexError.
def _vsc_ix(c, i):
    if -c.n <= i < c.n:
        return i
    raise IndexError('list index out of range')
# Generated by Viscosity: like iterating a list, re-checks the length each step.
def _vsc_iter(c):
    i = 0
    while i < c.n:
        yield i
        i += 1
# Generated by Viscosity: "ps" stored as a struct of arrays (fields x, y, vx, vy, m).
class _Vsc_ps:
    __slots__ = ('n', 'x', 'y', 'vx', 'vy', 'm')
    def __init__(self):
        self.n = 0
        self.x = _vsc_array('d')
        self.y = _vsc_array('d')
        self.vx = _vsc_array('d')
        self.vy = _vsc_array('d')
        self.m = _vsc_array('d')
    def append(self, v0, v1, v2, v3, v4):
        self.x.append(v0)
        self.y.append(v1)
        self.vx.append(v2)
        self.vy.append(v3)
        self.m.append(v4)
        self.n += 1
    def __len__(self):
        return self.n
    @classmethod
    def _of(cls, *v):
        c = cls()
        for i in range(0, len(v), 5):
            c.append(v[i + 0], v[i + 1], v[i + 2], v[i + 3], v[i + 4])
        return c

import time
from dataclasses import dataclass

@dataclass
class P:
    x: float
    y: float
    vx: float
    vy: float
    m: float

ps = _Vsc_ps()
for i in range(100000):
    ps.append(i * 0.5, 0.0, 1.0, -1.0, 2.0)

def step(arr, dt):
    for p in _vsc_iter(arr):
        arr.x[p] += arr.vx[p] * dt

t0 = time.perf_counter()
for f in range(20):
    step(ps, 0.016)
ms = (time.perf_counter() - t0) * 1000
s = 0.0
for p in _vsc_iter(ps):
    s += ps.x[p]
print('{"check": "%.6f", "ms": %.1f}' % (s, ms))
